/**
 * Scratch page for T3 — plays the three decoded OTT effects on demand and prints the
 * note table next to each button, so the decode can be checked by ear and by eye.
 * Not part of the game; served at /audio.html.
 */
import { AudioPlayer, SOUND_IDS } from '../core/Audio';

const audio = new AudioPlayer();

function noteLabel(note: { note: string; octave?: number }): string {
  return note.octave === undefined ? note.note : `${note.note}${note.octave}`;
}

async function main(): Promise<void> {
  const root = document.getElementById('sounds')!;
  const status = document.getElementById('status')!;

  await audio.load();
  audio.installUnlockListeners();

  const refresh = (): void => {
    status.textContent = audio.unlocked
      ? `audio unlocked${audio.isMuted ? ' (muted)' : ''}`
      : 'click anywhere to unlock audio (browsers block autoplay)';
  };
  refresh();

  for (const id of SOUND_IDS) {
    const tone = audio.tone(id)!;

    const row = document.createElement('div');
    row.className = 'row';

    const button = document.createElement('button');
    button.textContent = `▶ ${id}`;
    button.addEventListener('click', () => {
      void audio.unlock().then(() => {
        audio.play(id);
        refresh();
      });
    });

    const info = document.createElement('code');
    info.textContent =
      `${tone.tempoBpm} bpm · ${tone.style} · ${tone.durationMs} ms · ` +
      tone.notes.map((n) => `${noteLabel(n)} (${n.durationMs}ms)`).join('  ');

    row.append(button, info);
    root.append(row);
  }

  const mute = document.getElementById('mute') as HTMLButtonElement;
  mute.addEventListener('click', () => {
    mute.textContent = audio.toggleMute() ? 'unmute' : 'mute';
    refresh();
  });
}

void main();
